export function exampleContent(kind){
  if(Object.hasOwn(STUDIO_LABELS,kind))return studioExample(kind);
  if(kind==='graph')return {types:[],relations:[],nodes:[{id:'mara',label:'Mara',type:'Person',properties:{},x:250,y:180},{id:'firma',label:'Beispiel GmbH',type:'Unternehmen',properties:{},x:620,y:300}],edges:[{id:'e1',from:'mara',to:'firma',label:'arbeitet bei'}]};
  if(kind==='dataset')return {columns:[{name:'produkt',type:'text'},{name:'kategorie',type:'text'},{name:'preis',type:'number'}],rows:[{produkt:'Notizbuch',kategorie:'Büro',preis:8.5},{produkt:'Lampe',kategorie:'Büro',preis:39},{produkt:'Flasche',kategorie:'Alltag',preis:19.9}]};
  if(kind==='network')return networkExample('xor');
  if(kind==='prompt')return {input:'Erkläre, was eine Graphdatenbank ist.',variants:[{name:'Kurz',system:'Antworte in zwei einfachen Sätzen.',prompt:'{{eingabe}}'},{name:'Mit Beispiel',system:'Erkläre für Einsteiger mit einem konkreten Beispiel.',prompt:'{{eingabe}}'}],runs:[]};
  return {text:'Mara arbeitet bei Beispiel GmbH. Das Unternehmen entwickelt Lernangebote.\n\nGraphen speichern Beziehungen zwischen Dingen. Eine Kante verbindet zwei Knoten.\n\nRAG sucht passende Textabschnitte und übergibt sie als Kontext an ein Sprachmodell.',size:120,overlap:20,chunks:[],question:'Wo arbeitet Mara?',hits:[],selected:[],answer:'',source:'Beispieltext'};
}

