  if(!pid){$('.lab-body').innerHTML='<div class="empty"><h3>Zuerst ein Projekt anlegen</h3><p>Graphen und Experimente werden in Projekten gespeichert.</p><a class="es-btn es-btn--primary" href="#projects">Zu den Projekten</a></div>';return()=>{};}
  function changed(){if(object?.kind==='graph'){const h=graphHistory(),next=JSON.stringify(object.content);if(next!==h.last){h.past.push(h.last);if(h.past.length>40)h.past.shift();h.future=[];h.last=next;}const undo=$('[data-lab="graph:undo"]'),redo=$('[data-lab="graph:redo"]');if(undo)undo.disabled=!h.past.length;if(redo)redo.disabled=!h.future.length;}dirty=true;setDirty(true);status('Ungespeicherte Änderungen');}

