  async function save(){if(!object||busy)return;busy=true;const savingObject=object,saveButton=$('[data-lab="save"]');if(saveButton){saveButton.disabled=true;saveButton.setAttribute('aria-busy','true');}status('Wird gespeichert …');try{const sent=JSON.stringify(object);const result=await api('lab.save',{...object,project:pid});if(disposed||object!==savingObject)return;if(JSON.stringify(object)===sent){if(object.kind==='graph')Object.assign(object,{...result.object,content:object.content});else object=result.object;dirty=false;setDirty(false);info.objects=info.objects.map(o=>o.id===object.id?structuredClone(object):o);status('Gespeichert · Version '+object.version);}else{object.version=result.object.version;status('Weitere Änderungen noch ungespeichert');}}catch(error){status('Speichern fehlgeschlagen');throw error;}finally{busy=false;if(saveButton){saveButton.disabled=false;saveButton.removeAttribute('aria-busy');}}}
