  async function create(kind,content=exampleContent(kind),name=LAB_LABELS[kind]){const r=await api('lab.save',{project:pid,kind,name,content});if(!kinds.includes(kind)){location.hash=(STUDIO_LABS[kind]?.route||(kind==='graph'?'graph':kind==='dataset'?'data-lab':'ai-lab'))+'?project='+pid+'&object='+r.object.id;return;}await reload(r.object.id);}
  const download=(value,name)=>{const url=URL.createObjectURL(new Blob([JSON.stringify(value,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
