    if(a==='code-example'){if(!object)throw Error('Zuerst ein Laborobjekt anlegen.');await save();return modal('Codebeispiel im Projekt anlegen','<label class="field"><span>Sprache</span><select name="language">'+[["python","Python",flags.python],["php","PHP",flags.php],["javascript","JavaScript / HTML",flags.html]].filter(v=>v[2]).map(([v,n])=>'<option value="'+v+'">'+n+'</option>').join('')+'</select></label>',async d=>{const language=d.get('language'),id=JSON.stringify(object.id);let path,content;if(language==='python'){path='experiment-'+Date.now()+'.py';content=object.kind==='graph'?`import academy\n\ngraph = academy.Graph(${id})\nprint(await graph.nodes())\nprint(await graph.edges())\n`:`import academy\n\nprint(await academy.get(${id}))\n`;}else if(language==='php'){path='experiment-'+Date.now()+'.php';content=object.kind==='graph'?`<?php\n$graph = academy_graph(${id});\necho '<pre>' . htmlspecialchars(print_r($graph->nodes(), true)) . '</pre>';\n`:`<?php\necho '<pre>' . htmlspecialchars(print_r(academy_call('get', ['id' => ${id}]), true)) . '</pre>';\n`;}else{path='experiment-'+Date.now()+'.html';content=`<!doctype html>\n<html lang="de"><meta charset="utf-8"><title>Mein Laborexperiment</title><h1>Projektdaten aus Code</h1><pre id="result">Lädt …</pre><script>\n(async () => {\n const result = await academy.${object.kind==='graph'?`graph(${id}).nodes()`:`get(${id})`};\n document.querySelector('#result').textContent = JSON.stringify(result, null, 2);\n})().catch(error => document.querySelector('#result').textContent = error.message);\n</script></html>`;}await api('file.save',{project:pid,path,content,version:0});ctx.openCode(projects.find(p=>p.id===pid),object,path);});}if(a==='refresh'){if(await leave())await reload(object?.id);return;}if(a==='save')return save();if(a==='code'){if(!await leave())return;const p=projects.find(p=>p.id===pid);onProject(pid);ctx.openCode(p,object);return;}
