    bindGraphDrag(stage,g,{changed,draw,chooseNode,fail,beginMove:()=>graphViewport?.freeze()});
    $$('[data-edge]').forEach(el=>el.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();action(el.dataset.lab).catch(fail);}});
    $$('[data-graph-neighbor]').forEach(el=>el.onclick=()=>{graphViewport.focus(el.dataset.graphNeighbor);chooseNode(el.dataset.graphNeighbor).catch(fail);});

    changeField('node-label',v=>{node.label=v;const el=$$('.graph-stage [data-node]').find(el=>el.dataset.node===nodeId);if(el){const chars=[...v];el.querySelector('.graph-node-label').textContent=chars.length>26?chars.slice(0,25).join('')+'…':v;el.setAttribute('aria-label',v+', '+node.type);el.querySelector('title').textContent=v+' · '+node.type;}$('.graph-inspector-title').textContent=v;changed();},'input');changeField('node-type',async v=>{const next=structuredClone(node);next.type=v;for(const f of completeGraphModel(g).types.find(t=>t.name===v)?.fields||[])if(!(f.name in next.properties))next.properties[f.name]=f.type==='number'?0:f.type==='boolean'?false:'';try{await commitGraphModel(setGraphNode(g,next));}catch(error){draw();throw error;}});$$('[data-prop]').forEach(el=>el.oninput=()=>{const field=g.types.find(t=>t.name===node.type)?.fields.find(f=>f.name===el.dataset.prop);const type=field?.type||typeof node.properties[el.dataset.prop];node.properties[el.dataset.prop]=el.value===''&&type!=='text'&&type!=='string'?null:type==='number'?Number(el.value):type==='boolean'?el.value==='true':el.value;changed();});
